import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Network troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/network-issues.md","filePath":"troubleshooting/network-issues.md"}'),i={name:"troubleshooting/network-issues.md"};function n(c,e,d,r,l,h){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="network-troubleshooting" tabindex="-1">Network troubleshooting <a class="header-anchor" href="#network-troubleshooting" aria-label="Permalink to &quot;Network troubleshooting&quot;">​</a></h1><p>Ordered triage first, then the four deep chains: DHCP, DNS, TLS self-signed refusal, and the per-NIC <code>init failed</code> template.</p><h2 id="ordered-triage" tabindex="-1">Ordered triage <a class="header-anchor" href="#ordered-triage" aria-label="Permalink to &quot;Ordered triage&quot;">​</a></h2><p>Run <code>net-tool</code> and walk the menu, or use the classic spellings:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lspci                  (is the NIC on the bus?)</span></span>
<span class="line"><span>ush&gt; ip                     (address bound? 0.0.0.0 = none)</span></span>
<span class="line"><span>ush&gt; dhcp                   (address + gateway + DNS in one shot)</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2          (ICMP to the QEMU gateway)</span></span>
<span class="line"><span>ush&gt; arp                    (L2 resolution happened?)</span></span>
<span class="line"><span>ush&gt; dns example.com        (UDP + resolver OK?)</span></span>
<span class="line"><span>ush&gt; wget example.com 80 /  (full TCP + HTTP round trip)</span></span>
<span class="line"><span>ush&gt; tcpstats               (per-connection counters)</span></span></code></pre></div><p>Each step isolates a layer: bus → driver → L2 → L3 → L4 → application. The <code>update</code> wizard runs the first steps of exactly this ladder (IP probe → DHCP offer → DNS) before it ever checks for updates. <code>netstat</code> and <code>ifconfig</code> give the socket/interface pictures.</p><h2 id="the-dhcp-failure-chain" tabindex="-1">The DHCP failure chain <a class="header-anchor" href="#the-dhcp-failure-chain" aria-label="Permalink to &quot;The DHCP failure chain&quot;">​</a></h2><p>DHCP is a 4-step exchange — DISCOVER → OFFER → REQUEST → ACK on ports 68/67, magic cookie 0x63825363, xid 0x12345678; options parsed: 53 (msg type), 54 (server id, echoed in REQUEST), 1 (mask), 3 (gateway), 6 (DNS). The single failure string is <code>DHCP failed (timeout)</code> — the chain broke somewhere and the timeout swallowed the detail. Walk it:</p><ol><li><strong>Is there a NIC at all?</strong> <code>lspci</code>; the driver&#39;s status command (<code>e1000</code>, <code>rtl8139</code>, ...). <code>ip</code> shows the bound driver name.</li><li><strong>Did the driver bind?</strong> The <code>&lt;nic&gt;: init failed</code> template below.</li><li><strong>Is L2 alive?</strong> <code>arp</code> — after any traffic attempt there should be the gateway&#39;s MAC. Nothing there = no frames flow.</li><li><strong>Is the server answering?</strong> QEMU user-mode networking always answers (10.0.2.2 gateway + DNS forwarding, no host configuration needed). Real LAN: check the DHCP server&#39;s logs.</li><li><strong>Re-run</strong> <code>dhcp</code> — a success prints the anchor <code>DHCP success: IP=...</code> plus mask/gateway/DNS. Exit code reflects the outcome.</li></ol><p>If DHCP succeeds but the DNS field is empty, set it via a static <code>ip</code> or re-run DHCP (option 6 parsing is part of the chain).</p><h2 id="the-dns-failure-chain" tabindex="-1">The DNS failure chain <a class="header-anchor" href="#the-dns-failure-chain" aria-label="Permalink to &quot;The DNS failure chain&quot;">​</a></h2><p><code>dns &lt;name&gt;</code> (optionally <code>dns &lt;name&gt; aaaa|cname|mx|txt|ns|srv</code>). Failure strings: <code>DNS resolution failed</code>, <code>DNS resolution failed (timeout)</code>, <code>timeout</code>, and the per-record honest tails (<code>MX: no mail exchanger (or timeout)</code>, <code>AAAA: no IPv6 record (or timeout)</code>, <code>CNAME: not a CNAME or resolution failed</code>, ...).</p><ol><li><strong>Is there a DNS server configured?</strong> It comes from DHCP option 6 or a static <code>ip</code> round — <code>ifconfig</code> prints the DNS field.</li><li><strong>Is UDP flowing?</strong> <code>ping &lt;dns-server-ip&gt;</code>; <code>arp</code> for the gateway.</li><li><strong>Does the resolver work at all?</strong> <code>dnstest</code> (the battery, incl. built-in vectors against 10.0.2.2 and the update.json fixture).</li><li><strong>Poisoning guards</strong> (klog): <code>wrong transaction id dropped</code>, <code>query (QR=0) dropped</code>, <code>wrong qname echo dropped</code> — responses that fail validation are dropped silently. On a hostile LAN, known boundary: the transaction ID and response validation hardening is BUG-22 class.</li><li>Counters <code>UDP rx dropped (buffer full)</code> / <code>IP frag dropped</code> in netstat-family output mean overload, not misconfiguration.</li></ol><h2 id="tls-and-the-self-signed-refusal-https-e2e-item-0" tabindex="-1">TLS and the self-signed refusal (HTTPS E2E item 0) <a class="header-anchor" href="#tls-and-the-self-signed-refusal-https-e2e-item-0" aria-label="Permalink to &quot;TLS and the self-signed refusal (HTTPS E2E item 0)&quot;">​</a></h2><p>The trust model: certificate chains must anchor in the embedded root store (ISRG Root X1 etc., DER generated by <code>tools/embed_roots.py</code>). Verification failures print the exact stage and then refuse:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[tls] x509 verify failed: &lt;why&gt; - connection REFUSED</span></span></code></pre></div><p>where <code>&lt;why&gt;</code> is one of <code>bad certificate format</code>, <code>unsupported algorithm</code>, <code>signature verification failed</code>, <code>hostname mismatch</code>, <code>issuer certificate missing</code> (the X509_E_* family — <a href="./error-codes.html">error-codes.md</a>).</p><p><strong>HTTPS E2E item 0 semantics</strong>: the <em>zeroth</em> check of the HTTPS E2E suite is that a <strong>self-signed chain is REFUSED by default</strong>. This is the acceptance test for BUG-21 (the old code only warned and continued — a MITM needed just a self-signed cert). So:</p><ul><li>Seeing the REFUSED line with a self-signed server is <strong>correct behavior</strong>, not an outage.</li><li>Testing against a self-signed reference server requires the explicit opt-in: <code>config set tls.insecure 1</code> (the E2E compatibility pass uses exactly this), and turning it back off afterwards.</li><li>Handshake step failures beyond verification (<code>ServerHello recv/parse failed</code>, <code>ServerHello legacy version mismatch</code>, <code>CertificateVerify recv failed</code>, <code>server Finished verify_data mismatch</code>, <code>record decrypt failed (AEAD open)</code>) name the broken step directly — read the message; TLS 1.2 with DHE-RSA-AES128-SHA256 (0x0067) is the reference negotiation.</li><li><code>wget https://host/path</code> is the client face (<code>https://</code> selects TLS, port 443 default).</li></ul><h2 id="the-per-nic-init-failed-template" tabindex="-1">The per-NIC <code>init failed</code> template <a class="header-anchor" href="#the-per-nic-init-failed-template" aria-label="Permalink to &quot;The per-NIC \`init failed\` template&quot;">​</a></h2><p>Every ethernet driver prints the same failure shape when its probe fails: <code>&lt;name&gt;: init failed</code> — <code>e1000e</code>, <code>igb</code>, <code>ixgbe</code>, <code>rtl8139</code>, <code>rtl8168</code> (rtl8169 face), <code>bcm57xx</code> (plus its special <code>bcm57xx: DMA memory above 4GiB - refused</code>). One unified triage:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lspci                       # 1. is the card on the bus at all?</span></span>
<span class="line"><span>ush&gt; pcidump 0:03.0              # 2. are the BARs sane? (use the real b:d.f)</span></span>
<span class="line"><span>ush&gt; e1000e                      # 3. the family status command</span></span>
<span class="line"><span>ush&gt; e1000e_test                 # 4. the family selftest</span></span>
<span class="line"><span>ush&gt; nic_rw_test                 # 5. generic NIC loopback</span></span>
<span class="line"><span>ush&gt; other_nic_test              # 6. best-effort families (3c59x/nForce/AR81xx/Marvell)</span></span></code></pre></div><ul><li>No PCI device → wrong QEMU flag or the card is not seated; QEMU&#39;s best-tested path is <code>-device e1000</code> on a user netdev.</li><li>Device present but <code>init failed</code> → BAR/DMA problems (<code>pcibars</code>, <code>pcie</code>); on bcm57xx specifically, DMA above 4 GiB is refused.</li><li>Status OK but no traffic → link/routing: <code>ifconfig</code> (link state), <code>route</code>, <code>arp</code>.</li><li><code>virtio TX timeout: avail_idx=... used_idx=...</code> — the virtio NIC stopped consuming descriptors; restart the VM/device, report if persistent.</li></ul><p>Wireless: <code>wifi</code> (status), <code>wifi scan</code> (passive scan — QEMU honestly reports no radio), <code>wifi test</code> (core + per-family selftest), <code>wifi sdio</code>. Security strings <code>WEP/WPA1/WPA2 (not supported)</code> are the honest state machine, not failures.</p><h2 id="ssh-sshd-specifics" tabindex="-1">SSH / sshd specifics <a class="header-anchor" href="#ssh-sshd-specifics" aria-label="Permalink to &quot;SSH / sshd specifics&quot;">​</a></h2><ul><li>Client defaults: port 2222, user <code>oc</code>, password <code>oc</code>; password <code>-</code> = publickey with <code>/etc/ssh_client_key</code> (falls back to password if the key is absent). Hostnames are DNS-resolved.</li><li>Host trust is TOFU: the first connection writes <code>/etc/ssh_known_hosts</code>; a changed key prints <code>[ssh] WARNING: HOST KEY CHANGED! (possible MITM)</code> and refuses — delete the entry only when you know why it changed. On a read-only /etc expect <code>[ssh] TOFU: cannot write /etc/ssh_known_hosts</code>.</li><li>Server: <code>sshd [port]</code> (default 22), one session at a time; second connections are refused (<code>too many connections (one session at a time)</code>). First boot generates the host key in the background (<code>host key file corrupt; regenerating</code>); if it cannot (<code>cannot obtain a per-installation host key - refusing to start sshd</code>), pre-seed <code>etc.img</code> with <code>tools/host_keygen_etc.py</code>.</li><li><strong>First connect stalls</strong>: the ARP cache is cold after DHCP — run one client-direction command first (<code>ping</code> the peer) to warm it.</li><li>TCG (no-KVM) QEMU is slow: RSA-2048 keygen can exceed 500 s — the E2E recipes pre-seed keys and use generous timeouts (banner 420 s).</li></ul><h2 id="qemu-specifics" tabindex="-1">QEMU specifics <a class="header-anchor" href="#qemu-specifics" aria-label="Permalink to &quot;QEMU specifics&quot;">​</a></h2><ul><li>User-mode networking always provides 10.0.2.2 (gateway) and DNS forwarding — no host configuration needed.</li><li>The default <code>-device e1000</code> is the best-tested path.</li><li>Two-instance tests: shared <code>-netdev socket,multicast=...</code> gives a real two-node link for the NIC tests.</li><li>Timing stability for network tests: QEMU&#39;s <code>-icount</code>.</li></ul><h2 id="firewall-and-routing" tabindex="-1">Firewall and routing <a class="header-anchor" href="#firewall-and-routing" aria-label="Permalink to &quot;Firewall and routing&quot;">​</a></h2><p>The full netfilter face (<code>firewall</code> lists rules; <code>add</code>/<code>del</code>/ <code>policy</code>/<code>ct</code>/<code>reset</code> manage them):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; firewall                                    # list rules + policies</span></span>
<span class="line"><span>ush&gt; firewall add in drop tcp port 22            # drop inbound SSH</span></span>
<span class="line"><span>ush&gt; firewall del 1                              # remove rule 1</span></span>
<span class="line"><span>ush&gt; firewall policy in accept                   # chain default</span></span>
<span class="line"><span>ush&gt; firewall ct                                 # conntrack table</span></span>
<span class="line"><span>ush&gt; firewall reset                              # rules + conntrack + policies</span></span></code></pre></div><ul><li><code>rule not found</code> — the <code>del &lt;n&gt;</code> index was stale; re-list first.</li><li>Ping stops working after experiments — check the input-drop rules and <code>firewall reset</code> (it also clears conntrack and policies — that is the point).</li><li><code>nf_test</code> is the self-verifying battery (input drop + hits, rule removal restores ping).</li></ul><p>Routing: <code>route</code> shows the default + up to 16 custom entries; <code>route add &lt;dst&gt; &lt;mask&gt; &lt;gw&gt;</code> / <code>route del &lt;dst&gt; &lt;mask&gt;</code>. A <code>connect failed</code> with a present gateway usually means the peer, not the table — but an ARP entry that expired mid-session can dead-wait (known BUG-24 class under retransmit pressure): re-<code>ping</code> the peer to re-resolve.</p><h2 id="counters-that-tell-the-story" tabindex="-1">Counters that tell the story <a class="header-anchor" href="#counters-that-tell-the-story" aria-label="Permalink to &quot;Counters that tell the story&quot;">​</a></h2><ul><li><code>netstat</code> — sockets and connection statistics.</li><li><code>tcpstats</code> — per-connection state, cwnd/ssthresh/mss/rto, retransmit queue length, dup ACKs, timestamps, cc=cubic, w_max, sack, srtt/rttvar. RTO climbing + dup_acks growing = loss on the path.</li><li><code> UDP rx dropped (buffer full): &lt;n&gt;</code> / <code> IP frag dropped: &lt;n&gt;</code> (statistics output) — overload counters, not configuration errors.</li><li><code>arp</code> — the 16-entry cache; the gateway&#39;s MAC should appear after any traffic. An empty cache with a bound IP means L2 is dead (driver/link).</li><li><code>ifconfig</code> — read-only: driver name, HWaddr, inet, mask, gateway, DNS, link state, RX/TX counters. <code>ip</code> shows the same address block; <code>ip &lt;a&gt; &lt;m&gt; &lt;g&gt;</code> is the static-set form (the wizard&#39;s static-IP path asks the three fields in exactly this order).</li></ul><h2 id="two-node-and-host-access-setups" tabindex="-1">Two-node and host-access setups <a class="header-anchor" href="#two-node-and-host-access-setups" aria-label="Permalink to &quot;Two-node and host-access setups&quot;">​</a></h2><ul><li>Host reaches guest <code>sshd</code>: <code>-netdev user,id=n1,hostfwd=tcp::2223-:22</code> then <code>sshd 22</code> in the guest; connect from the host to <code>localhost:2223</code>.</li><li>Real two-node link: shared <code>-netdev socket,multicast=...</code> on both instances (the NIC tests use it).</li><li>The BT stack is real E2E over COM2 H4 bytes (<code>bt test</code> against the <code>bt_test_peer.py</code> host peer).</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./error-catalog.html">error-catalog.md</a> §5.15-§5.19 — every net string</li><li><a href="./silent-failures.html">silent-failures.md</a> — quiet refusals, UDP drops</li><li><a href="./../manual/network.html">../manual/network.md</a> — the user guide</li><li><a href="./../manual/commands/wget.html">../manual/commands/wget.md</a>, <a href="./../manual/commands/ssh.html">../manual/commands/ssh.md</a></li></ul>`,39)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
